-- Choose the answer first, then draw six clues from the requested number of contexts.
create table ascent_game.ascent_target_clues (
 target text not null, context_name text not null, clue text not null,
 primary key(target,context_name,clue)
);
alter table ascent_game.ascent_target_clues enable row level security;
